function activeRating(t){const e=document.querySelector(t);if(!e){return}const i=e.querySelectorAll(".rating .star");if(!e){return}i.forEach((t=>{t.addEventListener("click",(function(t){const r=this.getAttribute("data-value");for(let t=0;t<i.length;t++){if(i[t].getAttribute("data-value")<=r){i[t].innerHTML=`<i class="bi bi-star-fill"></i>`}else{i[t].innerHTML=`<i class="bi bi-star"></i>`}}e.querySelector('input[name="rating-index"]').value=r}))}))}function initRating(t,e){const i=document.querySelector(t);if(!i){return}const r=i.querySelectorAll(".rating .star");if(!i){return}let n=parseInt(e);if(e-n>0){for(let t=0;t<r.length;t++){if(r[t].getAttribute("data-value")<=n){r[t].innerHTML=`<i class="bi bi-star-fill"></i>`}else if(r[t].getAttribute("data-value")==n+1){r[t].innerHTML=`<i class="bi bi-star-half">`}else{r[t].innerHTML=`<i class="bi bi-star"></i>`}}}else{for(let t=0;t<r.length;t++){if(r[t].getAttribute("data-value")<=e){r[t].innerHTML=`<i class="bi bi-star-fill"></i>`}else{r[t].innerHTML=`<i class="bi bi-star"></i>`}}}}